// Persistent collection rules are independent of the renderer and study packs.
import {WORLDS} from './worlds.js';
import {PETS,isStarterPet} from './pet-catalog.js';
export {PETS} from './pet-catalog.js';
import {settleRewards} from './rewards.js';
export const FOOD=[['apple','Apple',10,18,'🍎'],['carrot','Carrot',10,18,'🥕'],['fish','Fish treat',15,28,'🐟'],['meat','Meat treat',15,28,'🍖'],['berry','Magical berry',30,65,'🫐'],['dragonSnack','Dragon snack',40,90,'🌶️'],['candy','Star candy',40,90,'⭐'],['biscuit','Crystal biscuit',50,120,'🍪']].map(([id,name,price,xp,icon])=>({id,name,price,xp,icon,description:`A magical pet-safe treat. +${xp} XP. All companions can enjoy it.`}));
export const ACCESSORIES=[['cap','Explorer cap','head',50,1,'🧢'],['crown','Crystal crown','head',180,5,'👑'],['helmet','Moon helmet','head',90,1,'🪖'],['wizard','Wizard hat','head',120,3,'🧙'],['collar','Rainbow collar','neck',50,1,'🌈'],['scarf','Cozy scarf','neck',70,1,'🧣'],['pendant','Star pendant','neck',90,2,'🌟'],['necklace','Magic necklace','neck',150,4,'💠'],['cape','Hero cape','back',90,1,'🦸'],['pack','Tiny backpack','back',75,1,'🎒'],['wings','Decorative wings','back',200,5,'🪽'],['trail','Sparkling trail','effects',100,2,'✨'],['paws','Glowing paws','effects',120,3,'🐾'],['aura','Magic aura','effects',180,5,'🔮'],['crystals','Crystal orbit','effects',250,7,'💎']].map(([id,name,slot,price,level,icon])=>({id,name,slot,price,level,icon,description:`${slot} cosmetic · pet level ${level}. Fits every companion.`}));
export const ABILITIES={fetch:'Every 20 collected crystals earns 1 bonus crystal.',magnet:'Collect nearby crystals from a little farther away.',scout:'Shows an earlier warning for approaching obstacles.',hop:'Every 10 safe groups grants 5 extra pet XP.',shield:'Every 20 safe groups charges one shield.',dash:'Every 20 safe groups charges one Smash Dash.',recovery:'Heart recovery gives 3 seconds of extra protection.',bonus:'Every 20 collected crystals earns 2 bonus crystals.'};
export function collection(p){p.collection??={wallet:Math.floor(p.crystals||0),spent:0,pets:[],food:{},accessories:[],equipped:null,worlds:{}};return p.collection;}
export function petLevel(xp){let level=1;while(level<10&&xp>=level*level*60)level++;return level;}
export function petProgress(pet){const l=petLevel(pet.xp),lo=(l-1)*(l-1)*60,hi=l===10?lo:l*l*60;return {level:l,value:l===10?1:(pet.xp-lo)/(hi-lo),next:hi};}
export function equipped(p){const c=collection(p);return c.pets.find(pet=>pet.id===c.equipped)||null;}
export function addXP(p,amount){const pet=equipped(p);if(!pet)return null;const before=petLevel(pet.xp);pet.xp=Math.min(6000,pet.xp+Math.max(0,Math.floor(amount)));const after=petLevel(pet.xp);return after>before?{name:pet.name,level:after}:null;}
function transaction(p,kind,detail){p.economyEvents??=[];p.economyEvents.push({id:crypto.randomUUID(),kind,...detail,at:new Date().toISOString()});}
export function adopt(p,species,starter=false){const c=collection(p),type=PETS.find(x=>x.id===species);if(!type)throw Error('Choose a companion.');if(c.pets.some(x=>x.species===species))throw Error('You already adopted this species.');if(starter&&c.pets.length)throw Error('Your starter has already been chosen.');if(starter&&!isStarterPet(type))throw Error('Only Common pets are free starters.');const price=starter?0:type.price;if(c.wallet<price)throw Error('Collect a few more crystals first.');c.wallet-=price;c.spent+=price;const pet={id:species,species,name:type.name,xp:0,accessories:{}};c.pets.push(pet);c.equipped=pet.id;transaction(p,'adopt',{item:species,starter:!!starter});return pet;}
export function purchase(p,kind,id){if(kind==='pets')return adopt(p,id);const c=collection(p),item=(kind==='food'?FOOD:ACCESSORIES).find(x=>x.id===id);if(!item)throw Error('Unknown item.');if(kind!=='food'&&c.accessories.includes(id))throw Error('Already owned.');if(kind!=='food'&&petLevel(equipped(p)?.xp||0)<item.level)throw Error('Level up your equipped pet first.');if(c.wallet<item.price)throw Error('Collect a few more crystals first.');c.wallet-=item.price;c.spent+=item.price;if(kind==='food')c.food[id]=(c.food[id]||0)+1;else c.accessories.push(id);transaction(p,'purchase',{category:kind,item:id});return item;}
export function feed(p,petId,foodId){const c=collection(p),pet=c.pets.find(x=>x.id===petId),food=FOOD.find(x=>x.id===foodId);if(!pet||!food||!c.food[foodId])throw Error('Buy a treat first.');c.food[foodId]--;transaction(p,'feed',{item:foodId,pet:petId});const before=petLevel(pet.xp);pet.xp=Math.min(6000,pet.xp+food.xp);return petLevel(pet.xp)>before;}
export function dress(p,petId,itemId){const c=collection(p),pet=c.pets.find(x=>x.id===petId),item=ACCESSORIES.find(x=>x.id===itemId);if(!pet||!item||!c.accessories.includes(itemId)||petLevel(pet.xp)<item.level)throw Error('This accessory is not ready for this pet.');pet.accessories[item.slot]=pet.accessories[item.slot]===itemId?null:itemId;}
// Banking uses cumulative cursors in the same localStorage transaction as the run.
export function bankRun(p,r,pack){const c=collection(p),paid=settleRewards(p,r,pack||{id:r.packId,archived:false});p.crystals+=paid.coins;c.wallet+=paid.coins;if(paid.coins)transaction(p,'earn',{amount:paid.coins,source:'run',session:r.sessionId});return addXP(p,paid.xp);}
export function validateCollection(c){if(c===undefined)return true;if(!c||![c.wallet,c.spent].every(x=>Number.isSafeInteger(x)&&x>=0)||!Array.isArray(c.pets)||c.pets.length>60||!c.food||!Array.isArray(c.accessories)||!c.worlds||typeof c.worlds!=='object')return false;const ids=new Set();for(const p of c.pets){if(!p||ids.has(p.id)||p.id!==p.species||!PETS.some(x=>x.id===p.species)||typeof p.name!=='string'||p.name.length>24||!Number.isFinite(p.xp)||p.xp<0||p.xp>6000||!p.accessories)return false;ids.add(p.id);for(const [slot,id]of Object.entries(p.accessories))if(id&&(!c.accessories.includes(id)||!ACCESSORIES.some(a=>a.id===id&&a.slot===slot&&a.level<=petLevel(p.xp))))return false;}return (!c.equipped||ids.has(c.equipped))&&c.accessories.every(id=>ACCESSORIES.some(a=>a.id===id))&&new Set(c.accessories).size===c.accessories.length&&Object.entries(c.food).every(([id,n])=>FOOD.some(f=>f.id===id)&&Number.isSafeInteger(n)&&n>=0)&&Object.entries(c.worlds).every(([id,w])=>WORLDS[id]&&w&&[w.stages,w.finishes].every(n=>Number.isSafeInteger(n)&&n>=0));}
